/**
 * v2 blocks and items, as registries this app can actually use.
 *
 * `packages/gameplay` defines BLOCKS and ITEMS for the v1 ids only. The v2
 * contract ids - netherrack, farmland, the crops, the enchanting table - exist
 * in `@voxelcraft/core-types` and are generated by `@voxelcraft/world`, but no
 * registry entry describes them, so `BLOCKS.tryById(BLOCK_V2.FARMLAND)` is
 * `undefined`: nothing could be named, placed or dropped. Both packages are
 * frozen for this task, so apps/game builds merged registries here instead of
 * editing them.
 *
 * Each definition is spread from the stone definition, so the frozen fields
 * this app has no opinion about (texture keys, fluid, block entity, gravity,
 * redstone) keep their shape, and every field that matters for a v2 block is
 * then set explicitly. Rendering does not read these texture keys: the mesher
 * appearance table of `@voxelcraft/client` already covers the v2 ids.
 */
import {
	BLOCK,
	BLOCK_V2,
	INVENTORY,
	PORTAL,
	RENDER_LAYER,
	SOUND_GROUP,
	TOOL_CLASS,
	TOOL_TIER,
	type BlockDef,
	type BlockId,
	type ItemDef,
	type ItemId,
} from '@voxelcraft/core-types'
import {
	BLOCK_DEFS,
	ITEM_DEFS,
	ITEM_V2_DEFS,
	createBlockRegistry,
	createItemRegistry,
	drop,
	type GameplayBlockRegistry,
	type GameplayItemRegistry,
} from '@voxelcraft/gameplay'

function requireV1(id: BlockId): BlockDef {
	const def = BLOCK_DEFS.find((entry) => entry.id === id)
	if (def === undefined) throw new Error(`the v1 block table is missing block ${id}`)
	return def
}

const STONE_DEF: BlockDef = requireV1(BLOCK.STONE)

type V2Overrides = Partial<Omit<BlockDef, 'id' | 'name' | 'displayName'>>

function v2Block(
	id: BlockId,
	name: string,
	displayName: string,
	overrides: V2Overrides = {},
): BlockDef {
	return {
		...STONE_DEF,
		id,
		name,
		displayName,
		layer: RENDER_LAYER.Opaque,
		solid: true,
		fullCube: true,
		replaceable: false,
		opacity: 15,
		emission: 0,
		skyPassThrough: false,
		hardness: 1,
		toolClass: TOOL_CLASS.None,
		minTier: TOOL_TIER.None,
		soundGroup: SOUND_GROUP.Stone,
		flammable: false,
		drops: [drop(id)],
		itemId: id,
		...overrides,
	}
}

/** A crop: no collider, no light blocking, broken by hand, dropped by harvest. */
const CROP: V2Overrides = {
	layer: RENDER_LAYER.Cutout,
	solid: false,
	fullCube: false,
	opacity: 0,
	skyPassThrough: true,
	hardness: 0,
	soundGroup: SOUND_GROUP.Plant,
	flammable: true,
	drops: [],
}

