/**
 * Blocks that exist in the world but are never an inventory item: the portal
 * plane is lit by flint and steel, farmland comes from a hoe, and a crop comes
 * from planting a seed.
 */
const V2_NON_ITEM_BLOCKS: readonly BlockId[] = [
	BLOCK_V2.NETHER_PORTAL,
	BLOCK_V2.FARMLAND,
	BLOCK_V2.FARMLAND_WET,
	BLOCK_V2.WHEAT_CROP,
	BLOCK_V2.CARROT_CROP,
	BLOCK_V2.POTATO_CROP,
]

function blockItemOf(def: BlockDef): ItemDef {
	return {
		id: def.itemId,
		name: def.name,
		displayName: def.displayName,
		maxStack: INVENTORY.defaultMaxStack,
		texture: def.name,
		toolClass: TOOL_CLASS.None,
		tier: TOOL_TIER.None,
		durability: 0,
		attackDamage: 1,
		food: 0,
		fuelTicks: 0,
		placesBlock: def.id,
	}
}

/** Item definitions for the v2 blocks that can be held and placed. */
export const V2_BLOCK_ITEM_DEFS: readonly ItemDef[] = V2_BLOCK_DEFS.filter(
	(def) => !V2_NON_ITEM_BLOCKS.includes(def.id),
).map(blockItemOf)

/** v1 blocks plus every v2 block. */
export const BLOCKS_V2: GameplayBlockRegistry = createBlockRegistry([
	...BLOCK_DEFS,
	...V2_BLOCK_DEFS,
])

/** v1 items, the v2 items of gameplay, and the v2 block items. */
export const ITEMS_V2: GameplayItemRegistry = createItemRegistry([
	...ITEM_DEFS,
	...ITEM_V2_DEFS,
	...V2_BLOCK_ITEM_DEFS,
])

/** Stack limit resolver that also knows the v2 items. */
export function v2StackLimitOf(item: ItemId): number {
	return ITEMS_V2.maxStackOf(item)
}

/**
 * Inventory options for every call this app makes: without them the shared
 * `registryStackLimit` would resolve a v2 item against the v1 registry.
 */
export const V2_INVENTORY = { stackLimitOf: v2StackLimitOf }

/** Display name of an item, including the v2 items. */
export function itemDisplayName(item: ItemId): string {
	return ITEMS_V2.tryById(item)?.displayName ?? `Item ${item}`
}

/** Display name of a block, including the v2 blocks. */
export function blockDisplayName(id: BlockId): string {
	return BLOCKS_V2.tryById(id)?.displayName ?? `Block ${id}`
}

/** Durability of an item, including the v2 tools. 0 when not damageable. */
export function v2MaxDurabilityOf(item: ItemId): number {
	return ITEMS_V2.tryById(item)?.durability ?? 0
}

/** Block an item places, or `null` for items that are not blocks. */
export function v2PlacesBlock(item: ItemId): BlockId | null {
	return ITEMS_V2.tryById(item)?.placesBlock ?? null
}
